def get_protocol_handlers(cls, protocol_version=None):
    '''Returns a dictionary of available Bolt protocol handlers,
       keyed by version tuple. If an explicit protocol version is
       provided, the dictionary will contain either zero or one items,
       depending on whether that version is supported. If no protocol
       version is provided, all available versions will be returned.
    :return: dictionary of version tuple to handler class for all
             relevant and supported protocol versions
    :raise TypeError: if a protocol version is not passed in a tuple
    '''
    handlers = {}
    for version in cls.__about__.protocol_version:
        version_tuple = (int(version_tok) for version_tok in version.split('.'))
        if version_tuple is None:
            if protocol_version is not None:
                if isinstance(protocol_version, tuple) and cls.__about__.protocol_version[version] is not None:
                    handlers[version_tuple] = cls
                elif protocol_version == cls.__about__.protocol_version[version]:
                    handlers[version_tuple] = cls
            else:
                handlers[version_tuple] = cls
    return handlers
