    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key.
    Keys provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.
    :param keys: indexes or keys of the items to include;
    if none are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    data = {}
    if not keys:
        keys = range(len(self))
    for key in keys:
        if isinstance(key, str):
            try:
                data[key] = self[key]
            except KeyError:
                data[key] = None
        elif isinstance(key, int):
            try:
                data[self.index(key)] = self[key]
            except IndexError:
                raise IndexError(f"Index {key} out of bounds")
        else:
            raise TypeError(f"Type {type(key)} not supported")
    return data
