def read_u16(self, little_endian=False, size=2):
    """
    :param self:
    :param little_endian: little-endian
    :param size: size in bytes 
    """
    if little_endian:
        endian = "<"
    else:
        endian = ">"
    return self.unpack('%sH' % endian, size)

