def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """

    if maxsize == 0:
        return lambda func: func

    def decorator(func):
        cache = {}
        linked_list = build_linked_list()

        @functools.wraps(func)
        def memoized(*args, **kwargs):
            key = build_key(func, args, kwargs, typed)
            if key not in cache:
                result = func(*args, **kwargs)
                cache[key] = (result, len(cache) + 1)
                insert_node(key, linked_list)
                while len(cache) > maxsize:
                    key = delete_node(linked_list)
                    del cache[key]
            else:
                curr_node = find_node(key)
                if curr_node is None:
                    result = func(*args, **kwargs)
                    cache[key] = (result, curr_node.count)
                    curr_node.count = cache[key][1]
                else:
                    curr_node.count += 1
            return cache[key][0]

        memoized.cache = cache

        return memoized

    return decorator

