def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    tb = sys.exc_info()[2]
    if not tb:
        return ''.join(traceback.format_exception_only(type(e), e))
    tbinfo = traceback.extract_tb(tb)
    if not tbinfo:
        return ''.join(traceback.format_exception_only(type(e), e))
    path, line, function, source = tbinfo[-1]
    lines = traceback.format_exception(type(e), e, tb)
    stk = traceback.extract_stack(tb, max_level)
    path_ = []
    for p in stk:
        line, function, source = p
        if source:
            path_.append(source)
    stack = ''.join(lines)
    if not path_:
        return ''.join(lines)
    return ''.join(lines) + '{}{}{}{}'.format(os.linesep, path_[:max_path_level])
