class ExceptionFormatter(object):
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        try:
            exc_type = str(e.__class__)
            exc_args = e.message
            if exc_args:
                exc_args = str(e.message)
            if max_path_level:
                flattened_path = ', '.join(str(f) for f in traceback.extract_stack(limit=max_path_level))
            else:
                flattened_path = ''
            if max_level:
                flattened_stack = ', '.join(str(f) for f in traceback.extract_stack(limit=max_level))
            else:
                flattened_stack = ''
        except:
            return 'Exception formatting error: {!r} {!r}'.format(type(e), e)
        return 'Exception: {} ({}) - {}({})'.format(exc_type,
                                                    exc_args,
                                                    flattened_path,
                                                    flattened_stack)
