def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = [base for base in classes if isinstance(base, type)]
    base_dict = {base.__name__:base for base in bases}
    base_dict = {base.__name__:base for base in bases}
    for base in reversed(bases):
        for sub_base in base.__bases__:
            if sub_base.__name__ in base_dict:
                del base_dict[sub_base.__name__]
    return [base_dict[base] for base in base_dict]
