def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource_group in app.spec.manifest.keys():
        for resource_type, resource_list in app.spec.manifest[resource_group].items():
            for resource in resource_list:
                if not resource.observer_schema:
                    resource.observer_schema = {
                        "kind": resource.api_path[-2],
                        "apiVersion": resource.api_path[-1],
                        "metadata": {
                            "name": resource.name,
                            "namespace": resource.namespace,
                            "selfLink": resource.self_link,
                            "uid": resource.uid,
                        },
                        "spec": {
                            "type": resource.api_path[-2],
                            "kubernetes.io/yaml": yaml.dump(resource.body)
                        }
                    }
    return app

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    observer_schema = {}
    for resource in app.spec.manifest.items():
        if resource not in app.observer_schema:
            observer_schema[resource] = generate_default_observer_schema_for_resource(resource)
    return observer_schema

def generate_default_observer_schema_for_resource(resource):
    """Generate the default observer schema for a specific Kubernetes resource

    Args:
        resource (str): The name of the resource

    Returns:
        dict: The default observer schema for the resource
    """
    # Initialize an empty observer schema for the resource
    observer_schema = {}

    # Iterate through the attributes of the resource and generate a default observer schema for each one
    for attribute in resource.attributes:
        # Determine the type of the attribute, and use a default value based on that type
        if attribute.type == "string":
            default_value = ""
        elif attribute.type == "number":
            default_value = 0
        elif attribute.type == "bool":
            default_value = False
        else:
            default_value = None

        # Add the attribute and its default value to the observer schema
        observer_schema[attribute.name] = default_value

