def _eval_file(prefix, file_path):
    """
    Identifies the type of package: `asset` or `rendition`.

    Identifies the type of file and updates `packages` with the type and the address of the file in evaluation.

    Parameters
    ----------
    prefix : str
        filename without extension
    file_path : str
        file path

    Returns
    -------
    dict
    """
    if prefix == 'rendition':
        if file_path.endswith('.rendition'):
            return {'type': 'rendition', 'path': file_path}
        elif file_path.endswith('.composite'):
            return {'type': 'rendition', 'path': file_path + '.rendition'}
        else:
            raise ValueError("File is not a rendition")
    elif prefix == 'asset':
        if file_path.endswith('.asset'):
            return {'type': 'asset', 'path': file_path}
        else:
            raise ValueError("File is not an asset")
    else:
        raise ValueError("Prefix is not valid")
