def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        command = [commands]
    else:
        command = commands
    output = None
    try:
        output = subprocess.check_output(command, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT if hide_stderr else None, env=env)
    except subprocess.CalledProcessError as e:
        if e.returncode != 0:
            raise ProgramError(f"Command failed with return code {e.returncode}")
    return output.decode().strip()
