def size_to_bytes(size: str) -> int:
    size_lower = size.lower()

    # check if size is a number
    if size_lower.isdigit():
        return int(size)

    # check if size has a suffix
    if not size_lower.endswith(("k", "m", "g", "t", "p", "e")):
        return -1

    # convert size to bytes
    mapping = {
        "k": 1024,
        "m": 1024 ** 2,
        "g": 1024 ** 3,
        "t": 1024 ** 4,
        "p": 1024 ** 5,
        "e": 1024 ** 6
    }
    size_no_suffix = size[:-1]
    suffixed_number = size_no_suffix.isdigit()
    if suffixed_number:
        return int(size_no_suffix) * mapping[size_lower[-1]]
    else:
        return -1
