def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("alphabet must be a list of strings")
    if not isinstance(padding, int) and padding is not None:
        raise ValueError("padding must be either None or an integer")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must have at least two characters")

    if number == 0:
        return alphabet[0]

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    result.reverse()

    if padding is not None and len(result) < padding:
        result.extend(alphabet[0] for _ in range(padding - len(result)))

    return "".join(result)


