def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    pattern = r"([0-9]+)\s*([a-zA-Z]{2})"
    match = re.match(pattern, frequency)
    if not match:
        raise ValueError("Invalid frequency string")

    number = int(match.group(1))
    unit = match.group(2)
    unit_map = {"weeks": datetime.timedelta(weeks=1),
                "days": datetime.timedelta(days=1),
                "hours": datetime.timedelta(hours=1),
                "minutes": datetime.timedelta(minutes=1),
                "seconds": datetime.timedelta(seconds=1),
                "microseconds": datetime.timedelta(microseconds=1)}

    if unit not in unit_map:
        raise ValueError("Invalid unit of time")

    return datetime.timedelta(unit_map[unit] * number)

