def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    lines = text.split('\n')
    inside_code_block = False
    for line in lines:
        line = line.strip()
        if line.startswith('#'):
            tag = line[1:].strip()
            if not inside_code_block:
                tags.add(tag)
            if replacer:
                tag = replacer(tag)
        if line.startswith('```') or line.startswith('~~~'):
            inside_code_block = not inside_code_block
    return tags, text
