def fetch_content_type(url: str) -> Optional[str]:
    url = urlparse.urlsplit(url)
    if url.scheme != 'http' and url.scheme != 'https':
        return ''
    req = Urllib2HeadRequest(url, headers={'Host': url.netloc})
    resp = urlopen(req)
    try:
        if resp.code != 200 and url.scheme not in ('ftp', 'ftps'):
            return ''
        return resp.info().get('content-type', '')
    finally:
        resp.close()
    return ''

