def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    signature_algorithm = get_signature_algorithm(signature)
    if signature_algorithm == 'rsa-sha1':
        try:
            signing_key = load_rsa_public_key(public_key)
        except Exception as e:
            raise VerificationError(e)
        digest = get_sha1_digest(doc)
        verification_key = signing_key.public_key()
        try:
            verification_key.verify(digest, signature)
            return True
        except Exception as e:
            raise VerificationError(e)
    else:
        raise VerificationError('Unsupported signature algorithm')

