def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    webfinger = None
    if document.startswith("{"):
        try:
            webfinger = json.loads(document)
        except json.JSONDecodeError:
            pass
    elif document.startswith("<"):
        try:
            webfinger = webfinger_from_xrd(document)
        except ParseError:
            pass
    if not webfinger:
        raise ValueError("Invalid webfinger document")
    return webfinger

def webfinger_from_xrd(document: str) -> Dict:
    """
    Parse XRD webfinger document.

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    xrd = parseString(document)
    webfinger = {
        "id": xrd.get("@id", None),
        "aliases": xrd.get("aliases", []),
        "links": xrd.get("links", []),
    }
    for element in xrd.getElementsByTagName("subject"):
        node = element.firstChild
        if node is not None:
            webfinger["subject"] = node.data
    for element in xrd.getElementsByTagName("link"):
        attrs = element.attributes
        link_properties = {}
        for attr in attrs.items():
            if attr[0].startswith("@"):
                continue
            link_properties[attr[0]] = attr[1]
        link_properties["href"] = link_properties.get("href", "")
        webfinger["links"].append(link_properties)
    return webfinger

