def dict_insert(dic, val, key, *keys):
    if not keys:
        dic[key] = val
    else:
        sibling_keys = keys[:-1]
        key_to_insert = keys[-1]
        recursively_insert(dic, val, key_to_insert, sibling_keys)

def recursively_insert(dic, val, key_to_insert, sibling_keys):
    if sibling_keys:
        sibling_key = sibling_keys[0]
        if sibling_key not in dic:
            dic[sibling_key] = {}
        recursively_insert(dic[sibling_key], val, key_to_insert, sibling_keys[1:])
    else:
        dic[key_to_insert] = val
