def merge_extra_vars(vars_dict, extra_vars=None, inherit_key="inherit", inherit=False):
    """Extend ``vars_dict`` with ``extra_vars``

    Args:
        vars_dict (dict): Dictionary to merge extra-vars into
        extra_vars (list): List of extra-vars
        inherit_key (str): Key to check for inheritance
        inherit (bool): Whether or not to inherit

    Returns:
        dict: Merged dictionary

    Examples::
        >>> vars_dict = {"a": "A", "b": "B"}
        >>> extra_vars = [{"a": "A1", "b": "B1", "c": "C1"}, {"a": "A2", "d": "D2"}]
        >>> merge_extra_vars(vars_dict, extra_vars)
        {"a": "A1", "b": "B1", "c": "C1", "d": "D2"}
    """
    if isinstance(vars_dict, dict) and isinstance(extra_vars, list):
        for extra in extra_vars:
            if isinstance(extra, dict):
                vars_dict = extend_variables(vars_dict, extra, inherit_key, inherit)
            else:
                raise ValueError("Unable to extend: Dictionary expected")
        return vars_dict
    else:
        raise ValueError("Unable to extend: Dictionary and list expected")
